mapper.select:
SELECT
	id,
	account_no AS accountNo,
	photo_no AS photoNo,
	tag_no AS tagNo,
	created_by AS createdBy,
	created_at AS createdAt,
	tag_japanese_name AS tagJapaneseName,
	tag_english_name AS tagEnglishName
FROM
	photo.photo_tag_mst

	 AND account_no = #{accountNo, typeHandler=com.web.gallery.type_handler.AccountNoTypeHandler}
	 AND photo_no = #{photoNo, typeHandler=com.web.gallery.type_handler.PhotoNoTypeHandler}
	 AND tag_no = #{tagNo, typeHandler=com.web.gallery.type_handler.TagNoTypeHandler}
	 AND tag_japanese_name = #{tagJapaneseName, typeHandler=com.web.gallery.type_handler.TagJapaneseNameTypeHandler}
	 AND tag_english_name = #{tagEnglishName, typeHandler=com.web.gallery.type_handler.TagEnglishNameTypeHandler}

mapper.delete:
DELETE FROM
	photo.photo_tag_mst

	 AND account_no = #{accountNo, typeHandler=com.web.gallery.type_handler.AccountNoTypeHandler}
	 AND photo_no = #{photoNo, typeHandler=com.web.gallery.type_handler.PhotoNoTypeHandler}
	 AND tag_no = #{tagNo, typeHandler=com.web.gallery.type_handler.TagNoTypeHandler}
	 AND tag_japanese_name = #{tagJapaneseName, typeHandler=com.web.gallery.type_handler.TagJapaneseNameTypeHandler}
	 AND tag_english_name = #{tagEnglishName, typeHandler=com.web.gallery.type_handler.TagEnglishNameTypeHandler}
